"""Three concise legal documents. Confidential evidence stays in private/legal/."""
from html import escape
from legal_terms import load_terms

UPDATED = '3 November 2026'
UPDATED_FR = '3 novembre 2026'
LEGAL_EMAIL = 'legal@abstractmachines.dev'
DOCUMENTS = [load_terms()]

DOCUMENTS.append({'slug': 'privacy', 'titles': ('Privacy & Cookies', 'Confidentialité et cookies'), 'intros': ('How we handle website and early-access information.', 'Traitement des informations du site et de l’accès anticipé.'), 'draft': False, 'sections': [('controller', ('1. Who and what this covers', '1. Responsable et périmètre'), ('<p>Abstract Machines SAS, at the address in our <a href="/legal/terms/#company">company details</a>, controls the website and early-access information described here. Contact <a href="mailto:privacy@absmach.eu">privacy@absmach.eu</a>. Customer application processing requires the separate <a href="/legal/dpa/">DPA</a> and product-specific information before it starts.</p>', '<p>Abstract Machines SAS, à l’adresse des <a href="/legal/fr/terms/#company">mentions légales</a>, est responsable des traitements du site et de l’accès anticipé décrits ici. Contact : <a href="mailto:privacy@absmach.eu">privacy@absmach.eu</a>. Les traitements des applications clientes nécessitent l’<a href="/legal/fr/dpa/">accord de traitement</a> distinct et une information propre au produit avant leur début.</p>')), ('data', ('2. Data and purposes', '2. Données et finalités'), ('<p>The application form collects your name, email, app idea, project type/stage and role; company/project name is optional. Required fields let us assess and answer your request. Do not include third-party personal data or secrets. We also record submission time, consent version and campaign-source parameters. Hosting and abuse protection process IP addresses, browser signals and request metadata.</p><ul><li>Application review and related trial emails: your consent; this does not subscribe you to unrelated marketing.</li><li>Limited product research, campaign-source analysis, support and security: our legitimate interests in understanding demand and operating the service.</li><li>Optional audience/advertising measurement: your separate cookie consent.</li><li>Legal records and disputes: applicable legal obligations or legitimate interests in legal claims.</li></ul><p>You can withdraw consent without affecting prior lawful processing. We do not sell application information or make solely automated decisions with legal or similarly significant effects under this notice.</p>', '<p>Le formulaire recueille nom, courriel, idée, type/stade du projet et rôle ; le nom de société/projet est facultatif. Les champs requis permettent d’examiner votre demande et d’y répondre. N’incluez ni données personnelles de tiers ni secrets. Nous enregistrons aussi la date, la version du consentement et les paramètres de provenance de campagne. Hébergement et protection contre les abus traitent adresses IP, signaux du navigateur et métadonnées de requête.</p><ul><li>Examen de la candidature et courriels sur l’essai : votre consentement, sans abonnement à des publicités sans rapport.</li><li>Étude limitée des besoins et sources de campagne, assistance et sécurité : nos intérêts légitimes à comprendre la demande et exploiter le service.</li><li>Mesure facultative d’audience/publicité : votre consentement cookies distinct.</li><li>Dossiers légaux et litiges : obligations légales ou intérêts légitimes à défendre des droits.</li></ul><p>Le consentement peut être retiré sans affecter les traitements antérieurs licites. Nous ne vendons pas les candidatures et ne prenons pas, dans ce cadre, de décision exclusivement automatisée à effet juridique ou similaire significatif.</p>')), ('providers', ('3. Recipients and transfers', '3. Destinataires et transferts'), ('<p>Authorized staff and providers receive information needed for their tasks: website hosting/security, mailing-list hosting, email delivery and optional measurement. Cloudflare provides hosting and Turnstile bot protection; Google provides optional measurement. Advisers or authorities may receive data when necessary for legal matters.</p><p>Providers may process data outside the EEA, including in the United States. Transfers require an applicable adequacy decision or appropriate safeguards such as EU standard contractual clauses and necessary supplementary measures. Contact our privacy email for the applicable safeguards and a copy. Mailing-provider details, specific transfer safeguards and provider retention information remain to be completed.</p><p>For customer application processing, the provider identities, functions, locations and transfer safeguards are supplied privately with the DPA before authorization. Internal deployment diagrams are not public; confidentiality does not remove customers’ statutory information and audit rights.</p>', '<p>Les personnes habilitées et prestataires reçoivent les informations nécessaires : hébergement/sécurité, hébergement de la liste de diffusion, envoi des courriels et mesure facultative. Cloudflare fournit l’hébergement et Turnstile ; Google fournit la mesure facultative. Conseils et autorités peuvent recevoir des données lorsque nécessaire aux questions légales.</p><p>Des traitements peuvent avoir lieu hors EEE, notamment aux États-Unis. Les transferts nécessitent une décision d’adéquation applicable ou des garanties appropriées, telles que les clauses types européennes et mesures complémentaires nécessaires. Demandez les garanties applicables et leur copie à notre adresse de confidentialité. Les précisions sur la messagerie, les garanties de transfert et la conservation chez les prestataires restent à compléter.</p><p>Pour les applications clientes, les identités, missions, lieux et garanties de transfert des prestataires sont fournis de façon privée avec l’accord de traitement avant autorisation. Les schémas internes ne sont pas publics ; la confidentialité ne supprime pas les droits légaux d’information et d’audit.</p>')), ('retention', ('4. Retention and rights', '4. Conservation et droits'), ('<p>Applications are kept while needed for the requested early-access programme, subject to withdrawal or deletion requests. Limited consent/suppression records and information needed for legal obligations or disputes may be retained for those purposes and applicable periods. Provider-specific log and email retention periods remain to be completed.</p><p>You may request access, correction, erasure, restriction and portability where applicable; object to legitimate-interest processing and direct marketing; withdraw consent; and give applicable instructions for data after death. Email our privacy contact or use the unsubscribe link for trial emails. We respond within the GDPR deadlines, normally one month; a justified extension of up to two further months will be explained within that first month. You may complain directly to the <a href="https://www.cnil.fr/fr/plaintes">CNIL</a> or another competent authority.</p>', '<p>Les candidatures sont conservées tant qu’elles sont nécessaires au programme demandé, sous réserve du retrait ou d’une demande d’effacement. Des preuves limitées de consentement/opposition et les informations nécessaires aux obligations légales ou litiges peuvent subsister pour ces finalités et durées applicables. Les durées propres aux journaux et courriels des prestataires restent à compléter.</p><p>Vous pouvez demander accès, rectification, effacement, limitation et portabilité lorsque applicable ; vous opposer aux intérêts légitimes et à la prospection ; retirer votre consentement ; et donner les directives applicables après décès. Écrivez à notre contact confidentialité ou utilisez le lien de désinscription des courriels d’essai. Nous répondons dans les délais du RGPD, normalement un mois ; une prolongation justifiée de deux mois au maximum est expliquée pendant le premier mois. Vous pouvez saisir directement la <a href="https://www.cnil.fr/fr/plaintes">CNIL</a> ou une autre autorité compétente.</p>')), ('cookies', ('5. Cookies and browser storage', '5. Cookies et stockage'), ('<p><strong>Cookie Preferences</strong> in the footer lets you accept, reject or change optional measurement. Analytics measures visits and completed requests; marketing measures campaigns. Both are off by default. Google Tag Manager loads only after an optional category is accepted. Each tag must respect its category. The detailed measurement-cookie inventory, recipient entities and lifetimes remain to be completed.</p><ul><li>Consent choice: local storage, up to six months, then requested again.</li><li>Theme choice: local storage until changed or cleared.</li><li>Documentation menu position: session storage, consumed on navigation or ending with the browser session.</li><li>Turnstile: browser signals for signup abuse protection, loaded at the final form step; any additional browser storage duration remains to be completed.</li></ul><p>Demo state and unsent form text stay in page memory and reset on reload. See the <a href="https://policies.google.com/privacy">Google</a> and <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare</a> privacy information.</p>', '<p>Les <strong>préférences cookies</strong> en pied de page permettent d’accepter, refuser ou modifier la mesure facultative. L’audience mesure les visites et demandes abouties ; la publicité mesure les campagnes. Les deux sont désactivées par défaut. Google Tag Manager ne charge qu’après accord à une catégorie ; chaque balise doit respecter sa catégorie. L’inventaire détaillé des cookies de mesure, destinataires et durées reste à compléter.</p><ul><li>Choix cookies : stockage local jusqu’à six mois, puis nouvelle demande.</li><li>Thème : stockage local jusqu’à modification ou effacement.</li><li>Position du menu documentaire : stockage de session, consommé à la navigation ou supprimé à la fin de session.</li><li>Turnstile : signaux du navigateur contre les inscriptions abusives, chargé à la dernière étape ; toute durée de stockage supplémentaire reste à compléter.</li></ul><p>Les démonstrations et textes non envoyés restent en mémoire et se réinitialisent au rechargement. Voir les informations de <a href="https://policies.google.com/privacy">Google</a> et <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare</a>.</p>'))]})

DOCUMENTS.append({'slug': 'dpa', 'titles': ('Customer Data Processing Agreement', 'Accord de traitement des données clients'), 'intros': ('For customers whose personal data Atomic processes on their behalf.', 'Pour les clients dont Atomic traite les données personnelles pour leur compte.'), 'draft': True, 'sections': [('scope', ('1. Scope and instructions', '1. Périmètre et instructions'), ('<p>This agreement applies when accepted with the completed processing schedule. The customer acts as controller or authorized processor; Abstract Machines SAS acts as processor or subprocessor. Atomic processes personal data only on documented lawful instructions to provide the agreed service, including transfer instructions, unless EU or Member State law requires otherwise. It informs the customer before legally required processing unless EU or Member State law prohibits this, and immediately flags instructions considered unlawful. Independent use, including general model training, is not authorized by this agreement.</p>', '<p>Cet accord s’applique après acceptation avec la fiche de traitement complétée. Le client est responsable de traitement ou sous-traitant habilité ; Abstract Machines SAS est sous-traitant ou sous-traitant ultérieur. Atomic traite les données uniquement sur instructions licites documentées pour le service convenu, transferts compris, sauf obligation du droit de l’Union ou d’un État membre. Il informe le client avant le traitement imposé, sauf interdiction du droit de l’Union ou d’un État membre, et signale immédiatement les instructions estimées illicites. Aucun usage indépendant, dont l’entraînement général de modèles, n’est autorisé par cet accord.</p>')), ('security', ('2. Security and assistance', '2. Sécurité et assistance'), ('<p>Atomic binds authorized personnel to confidentiality and applies appropriate measures under GDPR Article 32, described in the schedule. Taking account of the processing and information available, it assists with individual rights, security, breach response, impact assessments and prior consultation under Articles 28 and 32–36. It notifies the customer without undue delay after becoming aware of a personal-data breach and supplies available information, with further details as obtained.</p>', '<p>Atomic soumet les personnes habilitées à confidentialité et applique les mesures appropriées de l’article 32 du RGPD, décrites dans la fiche. Compte tenu du traitement et des informations disponibles, il aide aux droits des personnes, à la sécurité, aux violations, analyses d’impact et consultations préalables selon les articles 28 et 32 à 36. Il avertit le client dans les meilleurs délais après connaissance d’une violation et fournit les informations disponibles, complétées à mesure.</p>')), ('subprocessors', ('3. Providers and transfers', '3. Prestataires et transferts'), ('<p>The customer’s written authorization covers the provider register supplied with the schedule. Additions or replacements require prior written information and a reasonable opportunity to object on data-protection grounds before processing begins. An unresolved justified objection prevents the affected processing; the affected service may end under the contract and applicable refund rights.</p><p>Atomic imposes equivalent applicable obligations on subprocessors by binding agreement and remains responsible under Article 28(4). Transfers outside the EEA require a valid GDPR Chapter V mechanism, matching the actual roles, with necessary assessments and safeguards. Provider identities, processing locations and transfer arrangements are recorded in the schedule.</p>', '<p>L’autorisation écrite du client couvre le registre fourni avec la fiche. Tout ajout ou remplacement nécessite une information écrite préalable et une possibilité raisonnable d’opposition pour protection des données avant traitement. Une opposition justifiée non résolue empêche le traitement concerné ; le service affecté peut prendre fin selon le contrat et les droits au remboursement applicables.</p><p>Atomic impose par accord contraignant des obligations applicables équivalentes aux sous-traitants ultérieurs et reste responsable selon l’article 28(4). Les transferts hors EEE nécessitent un mécanisme valable du chapitre V, adapté aux rôles réels, avec évaluations et garanties nécessaires. Identités, lieux et modalités figurent dans la fiche.</p>')), ('end', ('4. Return, deletion and accountability', '4. Restitution, suppression et contrôle'), ('<p>At the end of service, Atomic returns or deletes personal data at the customer’s choice and deletes remaining copies unless EU or Member State law requires retention. The agreed schedule describes retrieval and backup handling; retained data stays protected and restricted. Source-code export alone is not data return.</p><p>Atomic supplies information demonstrating compliance and permits and contributes to customer or authorized-auditor audits, including inspections. Reasonable confidentiality, security and scheduling arrangements must not defeat statutory rights. Evidence may be supplied privately.</p>', '<p>En fin de service, Atomic restitue ou supprime les données au choix du client et supprime les copies restantes sauf obligation de conservation du droit de l’Union ou d’un État membre. La fiche précise récupération et sauvegardes ; les données conservées restent protégées et limitées. L’export du code seul ne restitue pas les données.</p><p>Atomic fournit les informations démontrant la conformité et permet les audits, y compris les inspections, du client ou auditeur mandaté, auxquels il contribue. Des modalités raisonnables de confidentialité, sécurité et organisation ne peuvent neutraliser les droits légaux. Les preuves peuvent être fournies en privé.</p>')), ('schedule', ('5. Required processing schedule', '5. Fiche de traitement requise'), ('<p>Before processing, the parties complete and accept one schedule identifying: parties and roles; service, subject matter, duration, nature and purpose; data and people concerned; instructions and contacts; actual security measures; authorized providers and transfers; and return, deletion and backup arrangements. Sensitive data requires express agreement and suitable safeguards. This public template does not complete that schedule or execute an agreement. Contact <a href="mailto:privacy@absmach.eu">privacy@absmach.eu</a>.</p>', '<p>Avant traitement, les parties complètent et acceptent une fiche précisant : parties et rôles ; service, objet, durée, nature et finalités ; données et personnes ; instructions et contacts ; sécurité réelle ; prestataires et transferts autorisés ; restitution, suppression et sauvegardes. Les données sensibles nécessitent un accord exprès et des garanties adaptées. Ce modèle public ne complète pas la fiche et ne conclut aucun accord. Contact : <a href="mailto:privacy@absmach.eu">privacy@absmach.eu</a>.</p>'))]})

DOCUMENT_ORDER = ['terms', 'privacy', 'dpa']
FRENCH_PDF = '/legal/downloads/atomic-documents-juridiques-fr.pdf'

def render_legal_pages(page, hero):
    """English web pages; French text is supplied as a downloadable PDF."""
    documents = {d['slug']: d for d in DOCUMENTS}
    assert len(documents) == len(DOCUMENTS) == len(DOCUMENT_ORDER)
    download = f'<p><a href="{FRENCH_PDF}" download lang="fr" type="application/pdf">Télécharger les documents juridiques en français (PDF)</a></p>'
    intro = 'Company information, website notices and proposed service agreements.'
    status = 'Company details and website privacy information are provided here. The service terms and customer DPA remain proposed agreements until completed and accepted. This website does not sell subscriptions.'
    rows = ''.join(f'<a class="legal-row" href="/legal/{slug}/"><h2>{escape(documents[slug]["titles"][0])}</h2><p>{escape(documents[slug]["intros"][0])}</p><span aria-hidden="true">↗</span></a>' for slug in DOCUMENT_ORDER)
    page('legal', 'Legal documents', intro, hero('LEGAL', 'Legal documents', intro, extra=download) + f'<section class="page-section"><div class="container"><p>{status}</p><div class="legal-list">{rows}</div></div></section>')
    for slug in DOCUMENT_ORDER:
        d = documents[slug]
        title, intro = d['titles'][0], d['intros'][0]
        label = 'Proposed agreement · Not yet effective' if d['draft'] else 'Website information'
        note = ''
        if d['draft']:
            note = '<div class="notice"><strong>' + label + '</strong>These terms require completion of the stated operational and contractual prerequisites before acceptance. Reading them does not create a subscription or an executed DPA.</div>'
        toc = '<nav class="contents" aria-label="On this page"><strong>On this page</strong>' + ''.join(f'<a href="#{sid}">{escape(titles[0])}</a>' for sid, titles, _ in d['sections']) + '</nav>'
        body = ''.join(f'<section id="{sid}"><h2>{escape(titles[0])}</h2>{texts[0]}</section>' for sid, titles, texts in d['sections'])
        body += f'<div class="related"><a href="/legal/">← All legal documents</a><a href="mailto:{LEGAL_EMAIL}">{LEGAL_EMAIL}</a></div>'
        head = hero('LEGAL', escape(title), escape(intro), extra=download + f'<p class="article-meta">{label} · {d.get("updated_en", UPDATED)}</p>')
        page(f'legal/{slug}', title, intro, head + f'<div class="container reading-layout">{toc}<article class="prose">{note}{body}</article></div>', draft=d['draft'])
